import{_ as o,l as n,o as t,c as s,v as p,p as d,x as l,d as r,i as h,S as A,b as e}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"HiPPO 与 S4","description":"","frontmatter":{"title":"HiPPO 与 S4","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/hippo-s4.md","filePath":"llm/hippo-s4.md","lastUpdated":1789023840000}'),E={name:"llm/hippo-s4.md"};function m(P,a,c,u,B,S){const i=n("Mermaid");return t(),s("div",null,[a[1]||(a[1]=p('<h1 id="hippo-与-s4" tabindex="-1">HiPPO 与 S4 <a class="header-anchor" href="#hippo-与-s4" aria-label="Permalink to &quot;HiPPO 与 S4&quot;">​</a></h1><div class="epigraph"><p>把历史投影到一组正交多项式系数上，再用结构化的状态矩阵让这条投影可以在线更新。</p><footer>—— Gu et al., HiPPO, NeurIPS 2020；Gu, Goel &amp; Ré, Efficiently Modeling Long Sequences with Structured State Spaces, ICLR 2022</footer></div><p><a href="/llm/albert-param-sharing">上一课</a>仍在 Transformer 块里共享权重。主干的 <a href="/llm/mamba">Mamba</a> 已经用过选择性状态空间，但补层默认读者未必把 <strong>HiPPO 先验</strong> 和 <strong>S4 的结构化 \\(A\\)</strong> 当成可引用对象。本课把线性时不变 SSM 收成后课扫描、对偶、门控线性注意力都要指的骨架：状态 \\(h_t=Ah_{t-1}+Bx_t\\)，输出 \\(y_t=Ch_t\\)。不重写 Mamba 的选择机制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>注意力把过去写成可变长 KV 表。<a href="/llm/linear-attention">线性注意力</a> 把过去收成 \\(d_\\phi\\times d_v\\) 的矩阵，没有说明这矩阵该有什么动力学。普通 RNN 的 \\(A\\) 一学就容易谱半径失控：要么忘光，要么爆炸。缺口是：<strong>为长程记忆指定一类 \\(A\\)</strong>，使连续时间里对历史的最优投影，在离散更新后仍然可算、可训。</p><p>HiPPO 回答「记什么」：在线把到目前为止的信号投影到多项式基（Legendre 等）上，得到一组系数当状态。S4 回答「怎么算」：把对应的状态矩阵做成可对角化、可卷积的结构，训练时当长卷积，推理时当循环。</p><p><span class="marginnote">本课的 SSM 是时不变的：\\(A,B,C\\) 不随 \\(x_t\\) 变。选择发生在下一课。先把时不变骨架钉死，否则选择性会被写成又一种注意力。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>连续时间</p> \\[h&#39;(t)=Ah(t)+Bx(t),\\qquad y(t)=Ch(t), \\]<p>离散化时间步 \\(\\Delta\\)，得到 \\(h_t=\\overline{A}h_{t-1}+\\overline{B}x_t\\)。HiPPO 给出特定的 \\(A\\)（例如 Scaled Legendre），其状态分量是历史在正交多项式上的系数，对多项式信号在某种测度下最优。S4 把 \\(A\\) 参数化成对角加低秩等结构，用 Cauchy 核快速算卷积核 \\(K=\\overline{C}\\,\\overline{A}^{k}\\overline{B}\\)，整段 \\(y=K*x\\) 可并行。</p><p>初始化须靠近 HiPPO，而不是随机高斯 \\(A\\)：随机 \\(A\\) 很少能稳定地跨千步传递。这是本课与「随便堆一个线性层当 RNN」的差别。</p><h3 id="卷积与循环对偶" tabindex="-1">卷积与循环对偶 <a class="header-anchor" href="#卷积与循环对偶" aria-label="Permalink to &quot;卷积与循环对偶&quot;">​</a></h3><p>同一线性时不变系统，训练用卷积（对长度并行），推理用循环（常数状态）。后课的分块并行、状态空间对偶，都是在这条对偶上换算法，不改动力学族。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多项式投影解释了为何固定大小状态能近似长历史：不是记住每个 token，而是记住历史的光滑摘要。阶数（状态维）越高，能拟合的历史越不光滑。语言比音频更不光滑，所以纯 S4 做 LM 会缺选择——这正是 Mamba 课已经指出、下一课要在扫描里落地的缺口。</p><p>对角化让幂 \\(\\overline{A}^{k}\\) 变成逐分量的指数衰减，不同维度不同时间常数，对应多尺度记忆。低秩扰动保留 HiPPO 的耦合，避免完全解耦后表达力过弱。</p><p><span class="marginnote">\\(\\Delta\\) 是时间尺度。对离散 token，\\(\\Delta\\) 控制「这一格要不要多写入」。时不变时所有 token 共用 \\(\\Delta\\)，这是选择性扫描要拆开的点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>S4 适合均匀采样、长程光滑依赖（基因组、波形）。语言的内容稀疏记忆不是 HiPPO 的设定。不要用本课替代注意力的精确检索；后课线性召回瓶颈会回头量化这件事。实现上未结构化的稠密 \\(A\\) 无法走卷积核技巧，复杂度退回 \\(\\Theta(n N^2)\\)，\\(N\\) 为状态维。课序默认 S4 式结构，而不是稠密线性 RNN。</p>',20)),(t(),d(A,null,{default:l(()=>[h(i,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%E5%BA%8F%E5%88%97%22%5D%20--%3E%20Hippo%5B%22HiPPO%20%E7%BB%93%E6%9E%84%E7%9A%84%20A%22%5D%0A%20%20Hippo%20--%3E%20Disc%5B%22%E7%A6%BB%E6%95%A3%E5%8C%96%E5%BE%97%E5%88%B0%20A_bar%20B_bar%22%5D%0A%20%20Disc%20--%3E%20Conv%5B%22%E8%AE%AD%E7%BB%83%EF%BC%9A%E5%8D%B7%E7%A7%AF%E6%A0%B8%20K%22%5D%0A%20%20Disc%20--%3E%20Rec%5B%22%E6%8E%A8%E7%90%86%EF%BC%9A%E5%BE%AA%E7%8E%AF%E7%8A%B6%E6%80%81%22%5D%0A%20%20Conv%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%22%5D%0A%20%20Rec%20--%3E%20Y%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"HiPPO 指定把历史投影到多项式系数；S4 把对应 \\(A\\) 结构化，使卷积训练与循环推理对偶。"),e("li",null,"时不变 SSM 是后课扫描与对偶的骨架；选择尚未引入。"),e("li",null,"初始化应靠近 HiPPO，随机 \\(A\\) 几乎不能长程传递。"),e("li",null,"语言不光滑，纯 S4 不是 LM 的终点。"),e("li",null,"出处：Gu et al., NeurIPS 2020；Gu, Goel & Ré, ICLR 2022。")],-1))])}const b=o(E,[["render",m]]);export{f as __pageData,b as default};
